class Clouds{constructor(){this.clouds=[],this.container=document.createElement("div"),this.container.id="cloud-layer",document.body.appendChild(this.container),this.createClouds()}createClouds(){for(let t=0;t<10;t++){const t=document.createElement("div");t.className="cloud",t.style.top=25*Math.random()+"%",t.style.left=100*Math.random()+"%",t.style.animationDuration=40+50*Math.random()+"s",t.style.animationDelay=40*-Math.random()+"s",this.container.appendChild(t),this.clouds.push(t)}}update(){}}window.CloudSystem=new Clouds;